const edition = globalThis.makeSubjectEdition({"subject":"chip","year":2016,"grade":"3-4","contest":"Человек и природа","letters":"АБВГД","count":30,"language":"ru","points":3,"tasksFile":"задания_ЧИП-2016-3_4класс.pdf","answersFile":"reviewed-3-4.pdf","title":"Азия","reviewedKey":true}, [{"title":"Государство в двух частях","question":"Какая страна занимает территории как в Азии, так и в Европе?","choices":["Индия","Китай","Россия","Монголия","Узбекистан"],"answer":2,"points":3,"steps":["Часть России находится к западу от Уральских гор. Там расположены Москва и Санкт-Петербург.","Сибирь и российский Дальний Восток лежат в Азии. Остальные страны из списка находятся только в Азии."]},{"title":"Океан к востоку от Азии","question":"Какой океан омывает Азию с востока?","choices":["Атлантический","Индийский","Северный Ледовитый","Тихий","Южный"],"answer":3,"points":3,"steps":["К востоку от материка находятся берега российского Дальнего Востока, Китая и острова Японии.","За этими островами и побережьями простирается Тихий океан."]},{"title":"Снимки природных зон","question":"На каком снимке изображена тундра крайнего севера Азии?","choices":["","","","",""],"answer":4,"points":3,"steps":["В тундре короткое лето. Там обычно мало деревьев, а землю покрывают низкие растения.","На снимке Д виден открытый влажный пейзаж с невысокой растительностью. На других снимках есть лес или высокий травостой."],"optionFigures":[{"src":"assets/chip/2016/1-2-15-1.webp","alt":"Лес со светлыми пятнистыми стволами.","width":99,"height":89,"detailSrc":"assets/chip/2016/detail/1-2-15-1.webp","pixelWidth":124,"pixelHeight":111},{"src":"assets/chip/2016/3-4-03-2.webp","alt":"Луг с цветами и деревьями вдали.","width":93,"height":86,"detailSrc":"assets/chip/2016/detail/3-4-03-2.webp","pixelWidth":116,"pixelHeight":107},{"src":"assets/chip/2016/1-2-15-2.webp","alt":"Заросли с длинными пальмовыми листьями.","width":98,"height":88,"detailSrc":"assets/chip/2016/detail/1-2-15-2.webp","pixelWidth":123,"pixelHeight":111},{"src":"assets/chip/2016/1-2-15-4.webp","alt":"Густой лес из высоких узких зелёных крон.","width":99,"height":89,"detailSrc":"assets/chip/2016/detail/1-2-15-4.webp","pixelWidth":124,"pixelHeight":111},{"src":"assets/chip/2016/3-4-03-5.webp","alt":"Низкие кустики и водоёмы на открытой местности.","width":92,"height":86,"detailSrc":"assets/chip/2016/detail/3-4-03-5.webp","pixelWidth":115,"pixelHeight":107}]},{"title":"Горы между частями света","question":"Какая горная система служит одним из ориентиров западной границы Азии?","choices":["Алтай","Гималаи","Урал","Тянь-Шань","Памир"],"answer":2,"points":3,"steps":["Уральские горы протянулись с севера на юг. На карте по ним проводят часть границы между Европой и Азией.","Остальные названные системы лежат внутри Азии."]},{"title":"Зверь из гор Китая","question":"Какое из этих животных в природе встречается только в Китае?","choices":["","","","",""],"answer":3,"points":3,"steps":["Ищите зверя с белой головой и тёмными участками шерсти вокруг глаз и на ушах.","Это большая панда. В дикой природе она живёт в горных лесах Китая. У азиатских носорогов ареалы есть и в других странах."],"adaptation":"Вопрос ограничен Китаем. Среди снимков есть животные, которые также могут обитать в Азии.","optionFigures":[{"src":"assets/chip/2016/3-4-05-1.webp","alt":"Крупный зверь с широким туловищем и короткими ногами.","width":92,"height":79,"detailSrc":"assets/chip/2016/detail/3-4-05-1.webp","pixelWidth":115,"pixelHeight":99},{"src":"assets/chip/2016/3-4-05-2.webp","alt":"Копытное с длинной шеей и пятнами.","width":93,"height":79,"detailSrc":"assets/chip/2016/detail/3-4-05-2.webp","pixelWidth":116,"pixelHeight":99},{"src":"assets/chip/2016/3-4-05-3.webp","alt":"Массивный серый зверь с рогом на носу.","width":91,"height":79,"detailSrc":"assets/chip/2016/detail/3-4-05-3.webp","pixelWidth":114,"pixelHeight":99},{"src":"assets/chip/2016/3-4-05-4.webp","alt":"Чёрно-белый зверь с круглыми ушами.","width":93,"height":79,"detailSrc":"assets/chip/2016/detail/3-4-05-4.webp","pixelWidth":116,"pixelHeight":99},{"src":"assets/chip/2016/3-4-05-5.webp","alt":"Животное с хоботом и широкими ушами.","width":92,"height":79,"detailSrc":"assets/chip/2016/detail/3-4-05-5.webp","pixelWidth":115,"pixelHeight":99}]},{"title":"Чёрная Багира","question":"В «Книге джунглей» Киплинга Багира кажется чёрной, но на свету в её шерсти видны пятна. Какое это животное?","choices":["пантера","тигрица","львица","пума","рысь"],"answer":0,"points":3,"steps":["Багира живёт в индийских джунглях. При ярком свете можно заметить пятна, несмотря на тёмный цвет шерсти.","Так бывает у чёрного леопарда, которого называют чёрной пантерой."]},{"title":"Спутник Насреддина","question":"На каком животном ездит Ходжа Насреддин в народных историях?","choices":["конь","осёл","верблюд","рикша","вол"],"answer":1,"points":3,"steps":["В историях о Насреддине он часто путешествует верхом на небольшом вьючном животном с длинными ушами.","Это осёл. Некоторые истории рассказывают, как Насреддин едет на нём, сидя лицом к хвосту."]},{"title":"Сохатый у Чехова","question":"А. П. Чехов писал, что в сибирской тайге живут в том числе сохатые. Какого из этих зверей так называют?","choices":["","","","",""],"answer":4,"points":3,"steps":["Сохатым называют лося. Его широкие рога напоминают лопаты или перекладины.","Лось изображён под буквой Д. У него длинная морда и массивные рога с широкими площадками."],"optionFigures":[{"src":"assets/chip/2016/3-4-08-1.webp","alt":"Горное копытное с рогами, закрученными кольцами.","width":92,"height":85,"detailSrc":"assets/chip/2016/detail/3-4-08-1.webp","pixelWidth":115,"pixelHeight":106},{"src":"assets/chip/2016/3-4-08-2.webp","alt":"Серый зверь с острыми ушами.","width":93,"height":85,"detailSrc":"assets/chip/2016/detail/3-4-08-2.webp","pixelWidth":116,"pixelHeight":106},{"src":"assets/chip/2016/3-4-08-3.webp","alt":"Рыжевато-бурый зверёк на ветке.","width":91,"height":85,"detailSrc":"assets/chip/2016/detail/3-4-08-3.webp","pixelWidth":114,"pixelHeight":106},{"src":"assets/chip/2016/3-4-08-4.webp","alt":"Крупный бурый зверь с круглыми ушами.","width":93,"height":85,"detailSrc":"assets/chip/2016/detail/3-4-08-4.webp","pixelWidth":116,"pixelHeight":106},{"src":"assets/chip/2016/3-4-08-5.webp","alt":"Длинномордое копытное с широкими плоскими рогами.","width":92,"height":85,"detailSrc":"assets/chip/2016/detail/3-4-08-5.webp","pixelWidth":115,"pixelHeight":106}]},{"title":"Защита природы","question":"У какой из этих мер главная цель — сохранить природные сообщества?","choices":["мелиорация","добыча полезных ископаемых","создание заповедников","прокладка трубопроводов","строительство электростанций"],"answer":2,"points":3,"steps":["В заповеднике стараются сохранить природные процессы. Хозяйственная деятельность там ограничена.","Такая охрана нужна видам и местам их обитания. У строительства и добычи полезных ископаемых другие задачи."],"adaptation":"Уточнено, что спрашивается о цели меры."},{"title":"Головной убор на рисунке","question":"Как называется красный головной убор с кисточкой на рисунке?","choices":["тюбетейка","камилавка","фреска","ермолка","феска"],"answer":4,"points":3,"steps":["На рисунке шапочка имеет жёсткую форму, расширяющуюся книзу. Сбоку свисает тёмная кисточка.","Так выглядит феска. Тюбетейка обычно ближе по форме к голове, а фреска — вид настенной живописи."],"figure":{"src":"assets/chip/2016/3-4-10.webp","alt":"Красная шапочка с плоской верхушкой, орнаментом и чёрной кисточкой.","width":160,"height":168,"detailSrc":"assets/chip/2016/detail/3-4-10.webp","pixelWidth":200,"pixelHeight":210}},{"title":"Азия и полушария","question":"Какое утверждение о положении Азии относительно экватора верно?","choices":["экватор делит Азию на две равные части","Азия целиком в Северном полушарии","большая часть Азии в Северном полушарии","Азия целиком в Южном полушарии","большая часть Азии в Южном полушарии"],"answer":2,"points":4,"steps":["Материковая часть Азии находится севернее экватора. Некоторые азиатские острова, например Ява, лежат южнее него.","Значит, в обоих полушариях есть участки Азии, но основная площадь находится в Северном."]},{"title":"Костюмы бумажных кукол","question":"Традиционные костюмы какой страны изображены на бумажных куклах?","choices":["Китай","Вьетнам","Россия","Индия","Япония"],"answer":4,"points":4,"steps":["У фигур длинные запахивающиеся одежды с широкими рукавами. Талию пересекает широкий пояс.","Это кимоно и пояс оби, традиционные для Японии."],"figure":{"src":"assets/chip/2016/3-4-12.webp","alt":"Бумажные куклы в длинных нарядах с запахом и широкими поясами.","width":160,"height":160,"detailSrc":"assets/chip/2016/detail/3-4-12.webp","pixelWidth":200,"pixelHeight":200}},{"title":"Пролив между материками","question":"Какой пролив разделяет Азию и Северную Америку?","choices":["Гибралтарский","Магелланов","Гудзонов","Берингов","Санникова"],"answer":3,"points":4,"steps":["Ближе всего материки подходят друг к другу между Чукоткой и Аляской.","Вода между ними — Берингов пролив. К северу и к югу от него лежат моря двух океанов."]},{"title":"Зерновая культура Азии","question":"Какую зерновую культуру выращивают преимущественно в Азии и ежедневно едят жители многих стран?","choices":["овёс","рис","киноа","кукуруза","рожь"],"answer":1,"points":4,"steps":["Заливные поля с этой культурой характерны для многих областей Южной, Восточной и Юго-Восточной Азии.","Из её зёрен готовят кашу, лапшу и другие блюда. Это рис."]},{"title":"Фрукт на фотографии","question":"Как называется плод, разрезанный на фотографии?","choices":["манго","авокадо","папайя","дыня","маракуйя"],"answer":2,"points":4,"steps":["У плода яркая оранжевая мякоть. Внутри большая полость с множеством круглых тёмных семян.","Так выглядит папайя. У манго и авокадо в середине одна крупная косточка, а у дыни обычно светлые семена."],"figure":{"src":"assets/chip/2016/3-4-15.webp","alt":"Половинка плода с оранжевой мякотью и тёмными круглыми семенами.","width":136,"height":90,"detailSrc":"assets/chip/2016/detail/3-4-15.webp","pixelWidth":170,"pixelHeight":113}},{"title":"Направление сибирских рек","question":"В каком общем направлении текут Обь, Енисей и Лена?","choices":["с севера на юг","с юга на север","с востока на запад","с запада на восток","к озеру Байкал"],"answer":1,"points":4,"steps":["Истоки этих рек лежат южнее их устьев. Устья Оби и Енисея относятся к Карскому морю, а устье Лены — к морю Лаптевых.","Оба моря находятся на севере у сибирского побережья. Поэтому основное направление рек — с юга на север."]},{"title":"Цветочный символ Индии","question":"Какой цветок является национальным символом Индии?","choices":["","","","",""],"answer":0,"points":4,"steps":["Ищите водное растение с широкими лепестками. Цветок нередко поднимается над водой среди крупных округлых листьев.","Так выглядит лотос на снимке А. Лотос часто изображают в индийском искусстве."],"optionFigures":[{"src":"assets/chip/2016/3-4-17-1.webp","alt":"Розовый цветок с жёлтой серединкой над широким листом.","width":94,"height":67,"detailSrc":"assets/chip/2016/detail/3-4-17-1.webp","pixelWidth":117,"pixelHeight":83},{"src":"assets/chip/2016/3-4-17-2.webp","alt":"Много ярко-красных цветков на тонких стеблях.","width":94,"height":67,"detailSrc":"assets/chip/2016/detail/3-4-17-2.webp","pixelWidth":117,"pixelHeight":83},{"src":"assets/chip/2016/3-4-17-3.webp","alt":"Мягко-розовые цветки с многочисленными лепестками.","width":94,"height":66,"detailSrc":"assets/chip/2016/detail/3-4-17-3.webp","pixelWidth":118,"pixelHeight":83},{"src":"assets/chip/2016/3-4-17-4.webp","alt":"Светло-розовый цветок с широкими боковыми долями.","width":94,"height":67,"detailSrc":"assets/chip/2016/detail/3-4-17-4.webp","pixelWidth":117,"pixelHeight":83},{"src":"assets/chip/2016/3-4-17-5.webp","alt":"Густой красный цветок с большим количеством лепестков.","width":94,"height":67,"detailSrc":"assets/chip/2016/detail/3-4-17-5.webp","pixelWidth":117,"pixelHeight":83}]},{"title":"Ящерица в сказе Бажова","question":"Хозяйка Медной горы превращается в ящерицу. На каком снимке видна небольшая пятнистая ящерица с длинным тонким хвостом?","choices":["","","","",""],"answer":2,"points":4,"steps":["Под буквой В у зверька четыре ноги, пятнистая спина и тонкий хвост. Так выглядит небольшая ящерица, бегущая по камням.","На снимке Д тоже ящерица, но у неё массивное тело и толстый хвост. Остальные снимки показывают змею и земноводных."],"adaptation":"Добавлены признаки нужной ящерицы, поскольку в ряду две фотографии ящериц.","optionFigures":[{"src":"assets/chip/2016/3-4-18-1.webp","alt":"Приземистое животное с бугорками на коже.","width":94,"height":67,"detailSrc":"assets/chip/2016/detail/3-4-18-1.webp","pixelWidth":117,"pixelHeight":83},{"src":"assets/chip/2016/3-4-18-2.webp","alt":"Зелёное вытянутое животное без ног.","width":94,"height":67,"detailSrc":"assets/chip/2016/detail/3-4-18-2.webp","pixelWidth":117,"pixelHeight":83},{"src":"assets/chip/2016/3-4-18-3.webp","alt":"Четвероногое животное с пятнами и тонким хвостом.","width":94,"height":66,"detailSrc":"assets/chip/2016/detail/3-4-18-3.webp","pixelWidth":118,"pixelHeight":83},{"src":"assets/chip/2016/3-4-18-4.webp","alt":"Зеленоватое животное с гладкой кожей и сложенными задними ногами.","width":94,"height":67,"detailSrc":"assets/chip/2016/detail/3-4-18-4.webp","pixelWidth":117,"pixelHeight":83},{"src":"assets/chip/2016/3-4-18-5.webp","alt":"Массивное четвероногое животное на камнях, с утолщённым хвостом.","width":94,"height":67,"detailSrc":"assets/chip/2016/detail/3-4-18-5.webp","pixelWidth":117,"pixelHeight":83}]},{"title":"Мягкая рухлядь","question":"Что на Руси называли «мягкой рухлядью», которую доставляли из Сибири?","choices":["валенки","пушнина","золото","чёрная икра","шерсть"],"answer":1,"points":4,"steps":["Это старое торговое название. Так называли шкурки зверей с ценным мехом, например соболей.","Мех и шкурки вместе называют пушниной. Они были важным товаром в торговле с Сибирью."]},{"title":"Вьючные звери в горах","question":"Каких вьючных животных Василий Верещагин изобразил в этом караване?","choices":["яки","мулы","ослы","волы","ламы"],"answer":0,"points":4,"steps":["На животных видны поклажа и длинная шерсть по бокам. У них крепкие ноги и широкие рога.","Это яки. В высокогорных районах Азии они помогают перевозить грузы по каменистым тропам."],"figure":{"src":"assets/chip/2016/3-4-20.webp","alt":"Караван длинношёрстных рогатых животных с грузом на горной тропе.","width":160,"height":122,"detailSrc":"assets/chip/2016/detail/3-4-20.webp","pixelWidth":200,"pixelHeight":152}},{"title":"Мавзолей на картине","question":"В какой стране находится Тадж-Махал, показанный на картине Василия Верещагина?","choices":["Узбекистан","Туркменистан","Бангладеш","Китай","Индия"],"answer":4,"points":5,"steps":["Белый мавзолей с высоким куполом и минаретами стоит у реки Ямуны в городе Агре.","Агра находится в Индии. Тадж-Махал построили при правителе Шах-Джахане."],"figure":{"src":"assets/chip/2016/3-4-21.webp","alt":"Светлый купол, тонкие башни и другие здания у реки.","width":120,"height":147,"detailSrc":"assets/chip/2016/detail/3-4-21.webp","pixelWidth":150,"pixelHeight":184}},{"title":"Древний пурпур","question":"Какой древний народ Восточного Средиземноморья прославился изготовлением пурпурного красителя из морских моллюсков?","choices":["японцы","жители Древнего Китая","древние римляне","финикийцы","ассирийцы"],"answer":3,"points":5,"steps":["Для пурпура использовали вещества, полученные из морских улиток. На окраску ткани требовалось много сырья, поэтому она была дорогой.","Знаменитый тирский пурпур связан с финикийским городом Тиром, который стоит на берегу Средиземного моря."],"adaptation":"Вопрос о традиции изготовления морского пурпура в Восточном Средиземноморье."},{"title":"Сильные морозы Якутии","question":"Почему посёлок Оймякон часто упоминают, рассказывая о климате Северного полушария?","choices":["он известен как один из северных полюсов холода","он расположен в географическом центре России","там самая низкая высота над уровнем моря во всей Азии","это столица Якутии","это географический центр Сибири"],"answer":0,"points":5,"steps":["Зимой в глубине Якутии воздух сильно остывает. Особенно холодно в котловинах и долинах, где скапливается тяжёлый холодный воздух.","Оймякон известен очень низкими зимними температурами. Поэтому его называют одним из полюсов холода Северного полушария."],"adaptation":"Уточнено, что речь об одном из самых холодных населённых мест."},{"title":"Зачем выращивают шелковицу","question":"Для чего в районах традиционного шелководства Китая выращивают тутовые деревья?","choices":["для топлива","для выкармливания гусениц","для варенья","для кормления скота","для живых изгородей"],"answer":1,"points":5,"steps":["Гусеницы тутового шелкопряда питаются листьями тутового дерева. После роста гусеница делает кокон из длинной нити.","Из этих нитей получают натуральный шёлк. Поэтому листья шелковицы нужны для выращивания гусениц."],"figure":{"src":"assets/chip/2016/3-4-24.webp","alt":"Зелёные листья на ветке и продолговатые ягоды.","width":160,"height":98,"detailSrc":"assets/chip/2016/detail/3-4-24.webp","pixelWidth":200,"pixelHeight":122}},{"title":"Электростанции и реки","question":"Какая из этих российских гидроэлектростанций находится за пределами Сибири?","choices":["Красноярская","Братская","Саяно-Шушенская","Саратовская","Усть-Илимская"],"answer":3,"points":5,"steps":["Красноярская и Саяно-Шушенская ГЭС стоят на Енисее. Братская и Усть-Илимская — на Ангаре.","Саратовская ГЭС стоит на Волге в европейской части России."],"adaptation":"Проверяется расположение станций. Список крупнейших станций со временем меняется."},{"title":"Поддержка в воде","question":"Папа держит сына так, что одинаковая часть его тела погружена в воду. Где вода сильнее всего помогает папе держать ребёнка?","choices":["на берегу, без воды","в пресной реке","в бассейне с пресной водой","в солёном море","во всех местах одинаково"],"answer":3,"points":5,"steps":["Вода выталкивает погружённую часть тела вверх. Чем плотнее вода, тем больше эта сила.","Солёная морская вода плотнее пресной. При одинаковом погружении в море папе легче поддерживать ребёнка."],"adaptation":"Уточнены одинаковое погружение и солёность воды.","figure":{"src":"assets/chip/2016/3-4-26.webp","alt":"Отец поддерживает ребёнка в воде.","width":136,"height":90,"detailSrc":"assets/chip/2016/detail/3-4-26.webp","pixelWidth":170,"pixelHeight":112}},{"title":"Белый журавль","question":"Стерх — редкий белый журавль, который гнездится в России. На каком снимке он изображён?","choices":["","","","",""],"answer":0,"points":5,"steps":["У стерха длинная шея, длинные красноватые ноги и красный участок голой кожи вокруг глаз. Белое тело помогает найти его в ряду, но одной окраски недостаточно.","Эти признаки вместе видны на снимке А. У аиста на снимке Д крупные чёрные участки сложенных крыльев, а у белой цапли В нет такого красного участка вокруг глаз."],"optionFigures":[{"src":"assets/chip/2016/3-4-27-1.webp","alt":"Белая длинноногая птица с красноватым участком у клюва.","width":94,"height":86,"detailSrc":"assets/chip/2016/detail/3-4-27-1.webp","pixelWidth":117,"pixelHeight":107},{"src":"assets/chip/2016/3-4-27-2.webp","alt":"Белая птица с изогнутой шеей и широкими тёмными лапами.","width":94,"height":86,"detailSrc":"assets/chip/2016/detail/3-4-27-2.webp","pixelWidth":117,"pixelHeight":107},{"src":"assets/chip/2016/3-4-27-3.webp","alt":"Белая птица с длинным жёлтым клювом и тёмными ногами.","width":94,"height":85,"detailSrc":"assets/chip/2016/detail/3-4-27-3.webp","pixelWidth":118,"pixelHeight":107},{"src":"assets/chip/2016/3-4-27-4.webp","alt":"Белая птица с оранжевым клювом на траве.","width":94,"height":86,"detailSrc":"assets/chip/2016/detail/3-4-27-4.webp","pixelWidth":117,"pixelHeight":107},{"src":"assets/chip/2016/3-4-27-5.webp","alt":"Белая длинноногая птица с чёрными крыльями и красным клювом.","width":94,"height":86,"detailSrc":"assets/chip/2016/detail/3-4-27-5.webp","pixelWidth":117,"pixelHeight":107}]},{"title":"Нерест в море","question":"Какая из этих рыб после жизни в пресной воде уходит на нерест в море?","choices":["сом","осётр","угорь","муксун","судак"],"answer":2,"points":5,"steps":["Европейский угорь растёт в реках и других водоёмах, а взрослые рыбы возвращаются далеко в Атлантику.","Икра угря развивается в море. У проходного осетра путь обратный: из моря вверх по рекам."]},{"title":"Солнце на флаге","question":"На флаге какой страны красный круг в центре обозначает солнце?","choices":["Монголия","Китай","Пакистан","Япония","Индия"],"answer":3,"points":5,"steps":["В центре белого полотнища изображён красный солнечный диск. На флагах других стран из списка есть полосы или другие знаки.","Так выглядит флаг Японии. С названием страны также связывают образ восходящего солнца."],"figure":{"src":"assets/chip/2016/3-4-29.svg","alt":"Красный круг в центре белого прямоугольника.","width":180,"height":120,"detailSrc":"assets/chip/2016/3-4-29.svg"}},{"title":"Страны, где растёт чай","question":"В какой из перечисленных стран в год конкурса производили больше всего чая?","choices":["Китай","Индия","Индонезия","Кения","Турция"],"answer":0,"points":5,"steps":["В Китае выращивание чая имеет многовековую историю. Чайные кусты растут во многих провинциях, например в Юньнани и Фуцзяни.","Индия тоже выращивает очень много чая, но среди приведённых стран по производству в 2016 году лидировал Китай."],"adaptation":"Сравнение отнесено к году проведения конкурса."}]);
